  string root=Path.Combine(Path.GetTempPath(),"BeoUI "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var paths=Enumerable.Range(1,3).Select(i=>Source(root,i)).ToArray();Call(form,"AddFiles",(object)paths);var jobs=(List<BatchJob>)F(form,"jobs");Check(jobs.Count==3&&jobs.All(j=>j.Selected),"Imported files are selected by default");Check(((Button)F(form,"runBatch")).Text=="CHẠY 3 FILE","Primary action shows the number of files that will run");jobs[1].Selected=jobs[2].Selected=false;Call(form,"RefreshJobs");Check(((Button)F(form,"runBatch")).Text=="CHẠY 1 FILE"&&Convert.ToBoolean(grid.Rows[1].Cells["selected"].Value)==false,"Unchecked files are excluded from the run count");
  jobs[0].Progress.Begin();jobs[0].Progress.Update(15,"Measuring");jobs[0].Progress.Update(47,"Fitting");jobs[0].State=JobState.Running;Call(form,"RefreshBeoProgress");Check(Convert.ToInt32(grid.Rows[0].Cells["completion"].Value)==47&&Convert.ToString(grid.Rows[0].Cells["eta"].Value)=="Đang ước lượng","Live queue cells show actual progress and avoid a premature ETA");jobs[0].Progress.Finish(false);jobs[0].Progress.Restore(0,0,false);jobs[0].State=JobState.Queued;
  foreach(int t in new[]{0,1,2,3,4}){theme.SelectedIndex=t;Application.DoEvents();var p=form.CurrentBeoPalette;Check(grid.DefaultCellStyle.ForeColor==p.Text&&grid.BackgroundColor==p.Surface,"Theme "+t+" reaches the queue and text colors");}
  theme.SelectedIndex=2;float baseSize=grid.Font.SizeInPoints;font.SelectedIndex=2;Application.DoEvents();float large=grid.Font.SizeInPoints;theme.SelectedIndex=1;theme.SelectedIndex=2;Check(Math.Abs(grid.Font.SizeInPoints-large)<.01&&large>baseSize,"Changing themes does not compound font scaling");font.SelectedIndex=0;Check(Math.Abs(grid.Font.SizeInPoints-baseSize)<.01,"Font can return exactly to its original size");
  foreach(Size size in new[]{new Size(1440,960),new Size(1100,740)}){form.Size=size;form.Location=Point.Empty;Application.DoEvents();foreach(int scale in new[]{0,2}){font.SelectedIndex=scale;Application.DoEvents();Check(OnScreen(theme)&&OnScreen(font)&&OnScreen(file)&&OnScreen(ai),"Theme/font and both mode cards fit "+size+" scale "+scale);Check(OnScreen((Button)F(form,"runBatch"))&&OnScreen((Button)F(form,"beoBatchStop"))&&OnScreen((Button)F(form,"beoBatchResults")),"All three run actions fit "+size+" scale "+scale);Check(grid.ClientSize.Height>=115&&OnScreen(grid),"File table has usable height at "+size+" scale "+scale);Check(grid.Rows[0].Cells["completion"] is BeoProgressCell&&grid.Rows[0].Cells["selected"] is DataGridViewCheckBoxCell,"Progress and selection cells retain the intended types after refreshing rows");Check(grid.Columns["completion"].Visible&&grid.Columns["eta"].Visible,"Progress and ETA stay visible at "+size+" scale "+scale);Capture(form,"beo-batch-"+size.Width+"-scale"+(scale==0?100:125));}}
  font.SelectedIndex=0;form.Size=new Size(1440,960);theme.SelectedIndex=1;Application.DoEvents();Capture(form,"beo-batch-light");theme.SelectedIndex=4;Application.DoEvents();Capture(form,"beo-batch-ocean");theme.SelectedIndex=2;
  Check(tabs.TabPages.Cast<TabPage>().Any(t=>t.Text.Contains("Sao chép"))&&tabs.TabPages.Cast<TabPage>().Any(t=>t.Text.Contains("Thư viện")),"Voice clone and existing voice library remain accessible");tabs.SelectedIndex=0;((ComboBox)F(form,"voiceMode")).SelectedIndex=1;Application.DoEvents();Check(((ComboBox)F(form,"secondVoice")).Visible,"Two-voice routing remains available");((ComboBox)F(form,"voiceMode")).SelectedIndex=0;tabs.SelectedTab=batch;
  var originalJob=jobs[0];DateTime fakeNow=DateTime.UtcNow;var clockJob=new BatchJob(new RenderProgress(()=>fakeNow)){InputPath=originalJob.InputPath,SourceHash=originalJob.SourceHash,Cues=originalJob.Cues,Timed=true,Selected=true,State=JobState.Running};jobs[0]=clockJob;clockJob.Progress.Begin();clockJob.Progress.Update(10,"Đang đo chặng 1");fakeNow=fakeNow.AddSeconds(20);clockJob.Progress.Update(47,"Đang render · số đo đồng hồ kiểm thử");Call(form,"RefreshJobs");Call(form,"RefreshBeoProgress");Check(Convert.ToString(grid.Rows[0].Cells["eta"].Value).StartsWith("~")&&Convert.ToString(grid.Rows[0].Cells["eta"].Value).Contains("còn"),"Real ETA cell displays an approximate finish time and remaining duration from a deterministic processing clock");Check(((Label)F(form,"beoEtaLabel")).Text.Contains("~")&&((Label)F(form,"beoProgressLabel")).Text.Contains("47%"),"Queue footer and file row agree on the live measured completion and estimated deadline");Call(form,"SetBusy",true);Check(((Button)F(form,"beoBatchStop")).Enabled&&!((Button)F(form,"runBatch")).Enabled,"Active rendering keeps stop enabled and run/configuration locked");var side=(FlowLayoutPanel)F(form,"beoBatchSide");Check(side.Enabled&&BeoTheme.Walk(side).OfType<ComboBox>().All(c=>!c.Enabled)&&((Label)F(form,"workflowBatchHint")).Enabled,"Running locks editable controls while preserving readable theme labels and scrolling");((Label)F(form,"status")).Text="MINH HỌA TIẾN ĐỘ · Đồng hồ và dữ liệu kiểm thử";Capture(form,"beo-progress-eta-demo");Call(form,"SetBusy",false);jobs[0]=originalJob;Call(form,"RefreshJobs");
  grid.CurrentCell=grid.Rows[1].Cells["selected"];typeof(DataGridView).GetMethod("OnKeyDown",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(grid,new object[]{new KeyEventArgs(Keys.Space)});Check(jobs[1].Selected,"File-selection checkbox supports the keyboard space key");typeof(DataGridView).GetMethod("OnKeyDown",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(grid,new object[]{new KeyEventArgs(Keys.Space)});Check(!jobs[1].Selected,"Keyboard selection can return the queue to one selected file");grid.CurrentCell=grid.Rows[0].Cells[1];
  // Real UI run with intentionally missing engine/model: selected file only.
  await(Task)Call(form,"RunWorkflowBatch");Check(Directory.GetFiles(Path.GetDirectoryName(paths[0]),"*.txt").Length==1&&Directory.GetFiles(Path.GetDirectoryName(paths[1]),"*.txt").Length==0&&Directory.GetFiles(Path.GetDirectoryName(paths[2]),"*.txt").Length==0,"Actual queue execution processes selected files only, writing one report in file mode");Check(jobs[0].State==JobState.Failed&&jobs[0].Progress.Read().Percent<100,"A genuine missing-engine failure never displays completed 100%");Check(!((bool)F(form,"busy"))&&Application.OpenForms.Count==1,"Failure returns to the same window without extra repair dialogs");
  var appearance=BeoAppearance.Load(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"V15VoiceStudio","appearance.xml"));Check(appearance.Theme=="dark"&&appearance.Scale==100,"Theme and font preferences are persisted independently of voice settings");
  Console.WriteLine("TOTAL BEO UI "+count+" PASS. Real WinForms on Mono/Xvfb; intentional missing-engine run, no physical Windows/GPU claim.");
 }catch(Exception error){Console.WriteLine(error);code=1;}finally{form.Close();}};Application.Run(form);Environment.Exit(code);}
